"""##Feature Scaling

>MinMaxScaler
"""

def min_max_scaling(data, min_val=0, max_val=1):
    min_value = min(data)
    max_value = max(data)
    if min_value == max_value:
        # Avoid division by zero
        data = data.copy()
        data[:] = min_val
    else:
        # Scale the data between min_val and max_val
        scaled_data = (max_value - min_value) * (data - min_value) / (max_value - min_value)

        data = scaled_data + min_val

    return data

""">Z-ScoreScaler"""

def z_score_scaling(data):
    mean = np.mean(data)
    std_dev = np.std(data)

    # Check if the standard deviation is zero, and replace it with a small value to avoid zero division
    if std_dev == 0:
        std_dev = 1e-8

    # Perform z-score scaling
    z_scores = (data - mean) / std_dev

    return z_scores

